+func (m *directionModel) fit(f *inputVector, base float64, outcome int) {
+	g := float64(outcome) - m.probability(base, f)
+	for _, idx := range f.indices[:f.n] {
+		w := &m.weights[idx&weightMask]
+		w.gradient2 += float32(g * g)
+		step := float32(0.095 * g / math.Sqrt(1+float64(w.gradient2)))
+		if idx&(weightMask+1) != 0 {
+			step = -step
+		}
+		w.value += step
+		mix := &m.mixer[f.kind][idx>>24]
+		d := m.evidence(idx) * g
+		mix.gradient2 += float32(d * d)
+		mix.value += float32(0.025 * d / math.Sqrt(1+float64(mix.gradient2)))
+	}
+}
