+
+func (m *directionModel) probability(logit float64, f *inputVector) float64 {
+	for _, idx := range f.indices[:f.n] {
+		value := float64(m.weights[idx&weightMask].value)
+		if idx&(weightMask+1) != 0 {
+			value = -value
+		}
+		value += float64(m.mixer[f.kind][idx>>24].value) * m.evidence(idx)
+		logit += value
+	}
+	return 1 / (1 + math.Exp(-logit))
+}
+
+func estimateToken(prob float64) uint64 {
+	switch {
+	case prob < 0.005:
+		return 1
+	case prob < 0.10:
+		return 2
+	case prob < 0.5:
+		return 3
+	case prob < 0.90:
+		return 4
+	case prob < 0.995:
+		return 5
+	default:
+		return 6
+	}
+}
+
+func (p *predictor) predict(train bool) int {
+	if train {
+		return uncertain
+	}
+	m := &directions
+	m.Lock()
+	defer m.Unlock()
+	var f inputVector
+	if m.learning {
+		m.finish()
+	}
+	m.features(p, false, &f)
