+		}
+		return uncertain
+	}
+	if p.prior[0] == 0 && prob > 0.6 {
+		return taken
+	}
+	if p.prior[1] == 0 && p.prior[0] >= 4 && prob < 0.10 {
+		return notTaken
+	}
+	if prob > 0.94 {
+		return taken
+	}
+	if prob < 0.004 {
+		return notTaken
+	}
+	return uncertain
